const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=s=>s?new Date(s).toLocaleString():'—',dt=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);let user=null,data=null,view='overview',filter='all';
async function api(url,method='GET',body){let r=await fetch('/api'+url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.error||`Request failed (${r.status})`);return x}
let timer;function toast(message){let el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),3500)}async function run(action){try{await action()}catch(e){toast(e.message)}}const canEdit=()=>user?.role!=='viewer',admin=()=>['owner','admin'].includes(user?.role),owner=()=>user?.role==='owner';const plot=id=>data?.plots.find(p=>p.id===id)?.name||'Unknown plot';const latest=()=>data?.records.find(r=>r.type==='reading');
function authScreen(register=false){$('#content').innerHTML=`<div class="auth-wrap"><section class="form-card card"><div class="kicker">SECURE FARM WORKSPACE</div><h2>${register?'Create a farm account':'Sign in to CAFP'}</h2><p class="muted">Each farm has its own plots, devices, records and team.</p><form id="authForm" class="form-grid"><label class="field span2">Farm name<input name="farm" required maxlength="160" autocomplete="organization"></label>${register?'<label class="field span2">Your name<input name="name" required autocomplete="name"></label>':''}<label class="field span2">Email<input name="email" type="email" required autocomplete="username"></label><label class="field span2">Password<input name="password" type="password" minlength="12" required autocomplete="${register?'new-password':'current-password'}"></label><button class="primary span2">${register?'Create farm':'Sign in'}</button></form><button class="ghost" id="toggleAuth" style="margin-top:12px">${register?'Already have an account? Sign in':'New farm? Create an account'}</button><button class="ghost" id="joinFarm" style="margin-top:12px;margin-left:8px">Have an invitation? Join a farm</button><button class="ghost" id="getAppBeforeLogin" style="margin-top:12px">Get the app</button></section></div>`;$('#toggleAuth').onclick=()=>authScreen(!register);$('#joinFarm').onclick=joinScreen;$('#getAppBeforeLogin').onclick=downloadsScreen;$('#authForm').onsubmit=e=>{e.preventDefault();run(async()=>{let x=await api('/auth/'+(register?'register':'login'),'POST',Object.fromEntries(new FormData(e.target)));user=x.user;await refresh();setView('overview')})}}
async function refresh(){data=await api('/dashboard');$('#today').textContent=user.tenant_name+' · '+user.role;document.querySelectorAll('.nav').forEach(n=>n.hidden=['team','settings'].includes(n.dataset.view)&&!admin());$('#quickAdd').hidden=!canEdit();$('#logout').hidden=false}
function setView(v){view=v;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===v));let names={overview:'Farm overview',capture:'Capture field record',records:'Field records',plots:'Plots',devices:'Devices',team:'Team management',settings:'Settings & data',alerts:'Alert center',profile:'My profile',guide:'Getting started',downloads:'Get the app'};$('#title').textContent=names[v];$('#crumb').textContent=v.toUpperCase();render();window.scrollTo(0,0)}function bindNav(){document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>user?setView(b.dataset.view):toast('Sign in first'));$('#quickAdd').onclick=()=>setView('capture');$('#logout').onclick=()=>run(async()=>{await api('/auth/logout','POST');user=null;data=null;$('#logout').hidden=true;$('#quickAdd').hidden=true;authScreen()})}
function chart(){let rs=data.records.filter(r=>r.type==='reading'&&r.moisture!==''&&r.moisture!==null).slice(0,20).reverse();if(!rs.length)return '<div class="empty">No readings yet. Capture a measurement to see a trend.</div>';let points=rs.map((r,i)=>`${30+i*560/Math.max(1,rs.length-1)},${170-Number(r.moisture)*1.5}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 600 180" preserveAspectRatio="none" role="img" aria-label="Soil moisture trend">${[20,50,80].map(v=>`<line x1="30" x2="590" y1="${170-v*1.5}" y2="${170-v*1.5}" stroke="#e3eee2"/>`).join('')}<polyline points="${points}" fill="none" stroke="#24865a" stroke-width="3" vector-effect="non-scaling-stroke"/></svg></div><div class="chart-labels"><span>${fmt(rs[0].time)}</span><span>${fmt(rs.at(-1).time)}</span></div>`}
function overview(){let r=latest(),photo=data.records.find(x=>x.type==='photo');$('#content').innerHTML=`<section class="hero card"><div class="hero-copy"><div class="kicker">${esc(user.tenant_name.toUpperCase())} / LIVE DASHBOARD</div><h2>Every field record in one clear view.</h2><p>Monitor conditions, capture observations, and manage farm devices and your team.</p><button class="secondary" id="heroCapture">Capture record →</button></div><img src="./assets/concept.jpg" alt="Farm monitoring concept"></section><div class="stats"><div class="stat card"><div class="stat-label">Soil moisture</div><div class="stat-value">${r?.moisture!==''&&r?.moisture!=null?esc(r.moisture)+'%':'—'}</div><div class="stat-foot">Latest reading</div></div><div class="stat card"><div class="stat-label">Air temperature</div><div class="stat-value">${r?.temperature!==''&&r?.temperature!=null?esc(r.temperature)+'°C':'—'}</div><div class="stat-foot">Latest reading</div></div><div class="stat card"><div class="stat-label">Plots / devices</div><div class="stat-value">${data.summary.plots} / ${data.summary.devices}</div><div class="stat-foot">Configured for this farm</div></div><div class="stat card"><div class="stat-label">Alerts</div><div class="stat-value">${data.summary.alerts}</div><div class="stat-foot">Current thresholds</div></div></div><div class="grid"><div class="stack"><section class="panel card"><div class="section-head"><h2>Soil moisture trend</h2><button class="ghost" id="seeRecords">View records</button></div>${chart()}</section><section class="panel card"><div class="section-head"><h2>Recent activity</h2><span class="hint">${data.summary.readings} readings · ${data.summary.photos} photos</span></div>${data.records.slice(0,6).map(r=>`<div class="record-row"><span class="alert-icon ok">${r.type==='photo'?'▧':'◉'}</span><div class="row-main"><strong>${esc(plot(r.plot))} · ${esc(r.type)}</strong><small>${fmt(r.time)} · ${esc(r.source)}</small></div><span class="tag">${r.moisture!==''&&r.moisture!=null?esc(r.moisture)+'%':'—'}</span></div>`).join('')||'<div class="empty">No records yet.</div>'}</section></div><div class="stack"><section class="panel card"><h2>Latest plot image</h2>${photo?`<img class="photo" src="${photo.photo}" alt="Latest plot image"><div class="photo-meta"><strong>${esc(plot(photo.plot))}</strong><span>${fmt(photo.time)}</span></div>`:'<div class="empty">No plot photo yet.</div>'}</section><section class="panel card"><div class="section-head"><h2>Alerts</h2><span class="tag ${data.alerts.length?'warn':''}">${data.alerts.length}</span></div>${data.alerts.slice(0,6).map(a=>`<div class="alert-row"><span class="alert-icon critical">!</span><div class="row-main"><strong>${esc(a.metric==='moisture'?'Low soil moisture':'High temperature')} · ${esc(a.severity)}</strong><small>${esc(plot(a.plot_id))} · ${fmt(a.last_seen_at)} · ${esc(a.status)}</small></div></div>`).join('')||'<div class="empty">No threshold alerts.</div>'}<button class="secondary" id="manageAlerts">Manage alerts</button><button class="ghost" id="refreshOverview">Refresh</button></section></div></div>`;$('#heroCapture').onclick=()=>setView('capture');$('#seeRecords').onclick=()=>setView('records');$('#manageAlerts').onclick=()=>setView('alerts');$('#refreshOverview').onclick=()=>run(async()=>{await refresh();overview();toast('Dashboard refreshed')})}
function compress(file){return new Promise((resolve,reject)=>{let img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let c=document.createElement('canvas'),ratio=Math.min(1,1100/Math.max(img.width,img.height));c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.7))};img.onerror=reject;img.src=url})}
function capture(){if(!canEdit())return $('#content').innerHTML='<div class="empty">Viewer accounts cannot create records.</div>';$('#content').innerHTML=`<section class="form-card card"><h2>New field record</h2><form id="recordForm" class="form-grid"><label class="field">Type<select name="type" id="type"><option value="reading">Sensor / field reading</option><option value="photo">Plot photo</option></select></label><label class="field">Plot<select name="plot" required>${data.plots.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="field">Observed at<input name="time" type="datetime-local" value="${dt()}" required></label><label class="field reading">Soil moisture (%)<input name="moisture" type="number" min="0" max="100" step="0.1"></label><label class="field reading">Air temperature (°C)<input name="temperature" type="number" min="-50" max="70" step="0.1"></label><label class="field reading">Humidity (%)<input name="humidity" type="number" min="0" max="100" step="0.1"></label><label class="field span2 photo-input" hidden>Camera / image<input id="image" type="file" accept="image/*" capture="environment"><small>Compressed before upload; up to about 2 MB.</small></label><label class="field span2">Notes<textarea name="note"></textarea></label><button class="primary">Save record</button></form></section>`;$('#type').onchange=()=>{let photo=$('#type').value==='photo';document.querySelectorAll('.reading').forEach(x=>x.hidden=photo);$('.photo-input').hidden=!photo};$('#recordForm').onsubmit=e=>{e.preventDefault();run(async()=>{let f=new FormData(e.target),body=Object.fromEntries(f);body.time=new Date(body.time).toISOString();if(body.type==='photo'){let file=$('#image').files[0];if(!file)throw Error('Choose an image');body.photo=await compress(file)}else if(!['moisture','temperature','humidity'].some(k=>body[k]!==''))throw Error('Enter a measurement');await api('/records','POST',body);await refresh();toast('Record saved');setView('overview')})}}
function records(){let rs=data.records.filter(r=>filter==='all'||r.type===filter);$('#content').innerHTML=`<div class="toolbar"><select id="recordFilter"><option value="all">All records</option><option value="reading">Readings</option><option value="photo">Photos</option></select><button class="secondary" id="csvExport">Export CSV</button>${canEdit()?'<button class="primary" id="addRecord">+ Add record</button>':''}</div><section class="panel card"><div class="section-head"><h2>Record log</h2><span class="hint">${rs.length} shown</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Time</th><th>Plot</th><th>Type</th><th>Moisture</th><th>Temp</th><th>Humidity</th><th>Photo / notes</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${fmt(r.time)}</td><td>${esc(plot(r.plot))}</td><td>${esc(r.type)}</td><td>${esc(r.moisture||'—')}</td><td>${esc(r.temperature||'—')}</td><td>${esc(r.humidity||'—')}</td><td>${r.photo?`<a href="${r.photo}" target="_blank" rel="noopener">View photo</a>`:esc(r.note||'—')}</td><td>${canEdit()?`<button data-delete="${r.id}">Delete</button>`:''}</td></tr>`).join('')}</tbody></table></div>${rs.length?'':'<div class="empty">No matching records.</div>'}</section>`;$('#recordFilter').value=filter;$('#recordFilter').onchange=e=>{filter=e.target.value;records()};$('#csvExport').onclick=exportCsv;if($('#addRecord'))$('#addRecord').onclick=()=>setView('capture');document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>run(async()=>{if(!confirm('Delete this record?'))return;await api('/records/'+b.dataset.delete,'DELETE');await refresh();records();toast('Record deleted')}))}
function download(name,text,mime){let url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}function exportCsv(){let keys=['time','plot','type','moisture','temperature','humidity','source','note'];download('cafp-records.csv',[keys.join(','),...data.records.map(r=>keys.map(k=>csvCell(k==='plot'?plot(r.plot):r[k])).join(','))].join('\r\n'),'text/csv')}
function plots(){ $('#content').innerHTML=`<div class="plots-grid">${data.plots.map(p=>`<article class="plot-tile card"><h2>${esc(p.name)}</h2><small>${esc(p.crop)} · ${esc(p.area)}</small><div class="form-actions">${canEdit()?`<button class="ghost" data-edit="${p.id}">Edit</button>`:''}${admin()?`<button class="danger" data-delete="${p.id}">Delete</button>`:''}</div></article>`).join('')}</div>${canEdit()?`<section class="form-card card" style="margin-top:18px"><h2>Add plot</h2><form id="plotForm" class="form-grid"><label class="field">Name<input name="name" required></label><label class="field">Crop<input name="crop"></label><label class="field">Area<input name="area"></label><button class="primary">Add plot</button></form></section>`:''}`;if($('#plotForm'))$('#plotForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/plots','POST',Object.fromEntries(new FormData(e.target)));await refresh();plots();toast('Plot added')})};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>run(async()=>{let p=data.plots.find(x=>x.id===b.dataset.edit),name=prompt('Plot name',p.name);if(name===null)return;let crop=prompt('Crop',p.crop||'');if(crop===null)return;let area=prompt('Area',p.area||'');if(area===null)return;await api('/plots/'+p.id,'PUT',{name,crop,area});await refresh();plots()}));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>run(async()=>{if(!confirm('Delete this plot?'))return;await api('/plots/'+b.dataset.delete,'DELETE');await refresh();plots()}))}
function devices(){let ds=data.devices;$('#content').innerHTML=`<div class="banner">Create a device to receive a one-time ingest key. Save it securely. Send readings to POST /api/ingest with the key in the x-device-key header.</div><section class="panel card"><h2>Device inventory</h2>${ds.map(d=>`<div class="plot-row"><div class="row-main"><strong>${esc(d.label)} · ${esc(d.kind)}</strong><small>${esc(plot(d.plot_id))} · Last seen ${fmt(d.last_seen_at)}</small></div><span class="tag ${d.status==='online'?'':'warn'}">${esc(d.status)}</span>${admin()?`<button class="ghost" data-edit="${d.id}">Edit</button><button class="secondary" data-key="${d.id}">Rotate key</button><button class="danger" data-delete="${d.id}">Delete</button>`:''}</div>`).join('')||'<div class="empty">No devices configured.</div>'}</section>${admin()?`<section class="form-card card" style="margin-top:18px"><h2>Add device</h2><form id="deviceForm" class="form-grid"><label class="field">Label<input name="label" required></label><label class="field">Kind<select name="kind"><option>sensor</option><option>camera</option><option>gateway</option></select></label><label class="field">Plot<select name="plot"><option value="">Unassigned</option>${data.plots.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><button class="primary">Add device</button></form><div id="newKey"></div></section>`:''}`;if($('#deviceForm'))$('#deviceForm').onsubmit=e=>{e.preventDefault();run(async()=>{let x=await api('/devices','POST',Object.fromEntries(new FormData(e.target)));await refresh();devices();showKey(x.apiKey)})};document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>run(async()=>{if(!confirm('Rotate key? The old key stops working.'))return;let x=await api('/devices/'+b.dataset.key+'/rotate-key','POST');showKey(x.apiKey)}));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>run(async()=>{let d=ds.find(x=>x.id===b.dataset.edit),label=prompt('Device label',d.label);if(label===null)return;let status=prompt('Status: online, offline, maintenance',d.status);if(status===null)return;await api('/devices/'+d.id,'PUT',{label,status,kind:d.kind,plot:d.plot_id});await refresh();devices()}));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>run(async()=>{if(!confirm('Delete this device and revoke its key?'))return;await api('/devices/'+b.dataset.delete,'DELETE');await refresh();devices()}))}
function showKey(key){let box=$('#newKey');if(box)box.innerHTML=`<div class="banner"><strong>Copy this key now; it will not be shown again.</strong><input type="text" readonly value="${esc(key)}" style="width:100%;padding:10px;margin-top:8px"><button class="secondary" id="copyKey">Copy key</button></div>`;else alert('Save this one-time device key securely: '+key);if($('#copyKey'))$('#copyKey').onclick=()=>run(async()=>{await navigator.clipboard.writeText(key);toast('Key copied')})}
async function team(){let users=await api('/users');$('#content').innerHTML=`<section class="panel card"><h2>Farm team</h2>${users.map(u=>`<div class="plot-row"><div class="row-main"><strong>${esc(u.name)} · ${esc(u.email)}</strong><small>${esc(u.role)} · ${u.active?'Active':'Disabled'}</small></div>${u.role!=='owner'?`<button class="ghost" data-edit="${u.id}">Edit access</button>`:''}</div>`).join('')}</section><section class="form-card card" style="margin-top:18px"><h2>Add team member</h2><form id="userForm" class="form-grid"><label class="field">Name<input name="name" required></label><label class="field">Email<input name="email" type="email" required></label><label class="field">Temporary password (12+ characters)<input name="password" type="password" minlength="12" required></label><label class="field">Role<select name="role"><option value="viewer">Viewer</option><option value="operator">Operator</option>${owner()?'<option value="admin">Admin</option>':''}</select></label><button class="primary">Add member</button></form></section>`;$('#userForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/users','POST',Object.fromEntries(new FormData(e.target)));toast('Member added');team()})};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>run(async()=>{let u=users.find(x=>x.id===b.dataset.edit),name=prompt('Name',u.name);if(name===null)return;let role=prompt('Role: admin, operator, viewer',u.role);if(role===null)return;let active=confirm('Should this account remain active?');let password=prompt('New password (leave blank to keep existing)','');if(password===null)return;await api('/users/'+u.id,'PUT',{name,role,active,password});toast('Access updated');team()}))}
function parseCsv(text){let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(quote){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quote=false;else cell+=c}else if(c==='"')quote=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
async function settings(){let audit=await api('/audit');$('#content').innerHTML=`<div class="settings-grid"><section class="panel card"><h2>Alert thresholds</h2><form id="settingsForm"><label class="field">Low soil moisture (%)<input name="low" type="number" min="0" max="100" value="${esc(data.settings.low)}" required></label><label class="field">High temperature (°C)<input name="high" type="number" min="-50" max="70" value="${esc(data.settings.high)}" required></label><button class="primary" style="margin-top:14px">Save thresholds</button></form></section><section class="panel card"><h2>Import / export</h2><p class="muted">CSV fields: time, plot, moisture, temperature, humidity, note. Plot must already exist.</p><label class="field">Import readings CSV<input id="csvInput" type="file" accept=".csv,text/csv"></label><button class="secondary" id="exportBackup" style="margin-top:14px">Export JSON backup</button></section><section class="panel card span2"><h2>Recent audit events</h2>${audit.map(a=>`<div class="record-row"><div class="row-main"><strong>${esc(a.action)} ${esc(a.entity)}</strong><small>${fmt(a.created_at)} · ${esc(a.entity_id)}</small></div></div>`).join('')||'<div class="empty">No changes recorded.</div>'}</section></div>`;$('#settingsForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/settings','PUT',Object.fromEntries(new FormData(e.target)));await refresh();toast('Thresholds saved')})};$('#exportBackup').onclick=()=>download('cafp-backup.json',JSON.stringify({tenant:user.tenant_name,exportedAt:new Date().toISOString(),...data},null,2),'application/json');$('#csvInput').onchange=e=>run(async()=>{let rows=parseCsv(await e.target.files[0].text()),head=rows.shift().map(x=>x.trim().toLowerCase().replace(/^\ufeff/,''));if(!head.includes('time')||!head.includes('plot'))throw Error('CSV requires time and plot');let items=rows.map(row=>{let x=Object.fromEntries(head.map((h,i)=>[h,row[i]||''])),p=data.plots.find(p=>p.name.toLowerCase()===x.plot.toLowerCase()||p.id===x.plot);return{...x,plot:p?.id,type:'reading'}});let x=await api('/records/import','POST',{records:items});await refresh();toast(`Imported ${x.imported}; ${x.errors.length} skipped`);settings()})}
function render(){let f={overview,capture,records,plots,devices,team:teamScreen,settings,alerts,profile:profileScreen,guide:guideScreen,downloads:downloadsScreen}[view];let result=f();if(result?.catch)result.catch(e=>toast(e.message))}
bindNav();$('#logout').hidden=true;$('#quickAdd').hidden=true;$('#today').textContent='';run(async()=>{try{user=(await api('/me')).user;await refresh();setView('overview')}catch{if(new URLSearchParams(location.search).has('invite'))joinScreen();else authScreen()}});
